previewCss:
.darma-loader-darma-b8-nested-hexagons { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #ec4899); width: var(--loader-size, 76px); height: var(--loader-size, 76px); position: relative; }
.darma-loader-darma-b8-nested-hexagons span { position: absolute; inset: 0; margin: auto; clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%); }
.darma-loader-darma-b8-nested-hexagons span:nth-child(1) { background: var(--accent); animation: darma-loader-darma-b8-nested-hexagons-spin-cw calc(var(--loader-speed, 1s) * 2.6) linear infinite; }
.darma-loader-darma-b8-nested-hexagons span:nth-child(2) { inset: 22%; background: var(--accent-2); animation: darma-loader-darma-b8-nested-hexagons-spin-ccw calc(var(--loader-speed, 1s) * 2) linear infinite; }
.darma-loader-darma-b8-nested-hexagons span:nth-child(3) { inset: 44%; background: color-mix(in srgb, #fff 35%, var(--accent)); animation: darma-loader-darma-b8-nested-hexagons-spin-cw calc(var(--loader-speed, 1s) * 1.4) linear infinite; }
@keyframes darma-loader-darma-b8-nested-hexagons-spin-cw { to { transform: rotate(360deg); } }
@keyframes darma-loader-darma-b8-nested-hexagons-spin-ccw { to { transform: rotate(-360deg); } }

